    /// <summary>
    /// رموز أنواع المستندات، مقروءةً من الكتالوج المغلق نفسه لا من قائمة مكتوبة هنا.
    /// قائمةٌ ثانية مكتوبة بيد تنحرف عن الكتالوج عند أول إضافة، فيصف العقد مستنداً لا وجود له.
    /// </summary>
    private static IReadOnlyList<string> DocumentTypeCodes { get; } =
        [.. CapabilityCatalogue.DocumentTypes
            .Select(static definition => definition.Code.Value)
            .Order(StringComparer.Ordinal)];

    /// <summary>رموز القدرات في الكتالوج كلّه، بلا تكرار ومرتَّبة.</summary>
    private static IReadOnlyList<string> CapabilityCodes { get; } =
        [.. CapabilityCatalogue.DocumentTypes
            .SelectMany(static definition => definition.Capabilities)
            .Select(static capability => capability.Code.Value)
            .Distinct(StringComparer.Ordinal)
            .Order(StringComparer.Ordinal)];

    private static void WriteDocumentTypeParameter(Utf8JsonWriter w)
    {
        w.WriteStartObject();
        w.WriteString("name", "documentType");
        w.WriteString("in", "path");
        w.WriteBoolean("required", true);
        w.WriteString("description",
            "رمز نوع المستند من المجموعة المغلقة. / The document type code from the closed set.");
        w.WriteStartObject("schema");
        w.WriteString("type", "string");
        w.WriteStartArray("enum");
        foreach (string code in DocumentTypeCodes)
        {
            w.WriteStringValue(code);
        }

        w.WriteEndArray();
        w.WriteEndObject();
        w.WriteEndObject();
    }

    /// <summary>أعضاء تعداد جواب مراكز التكلفة، مقروءةً من التعداد نفسه لا من قائمة مكتوبة هنا.</summary>
    /// <summary>
    /// أنواع الحسابات وجوانبها وأنماط عملاتها — <b>قوائم مغلقة فعلاً</b>، وإغلاقها مفروض
    /// في المخطّط بقيود تحقّق (<c>ck_account_type</c> و<c>ck_account_natural_side</c>
    /// و<c>ck_account_currency_mode</c>) لا باتفاق. ولذلك تُنشر <c>enum</c>.
    /// <para>
    /// <b>وما ليس مغلقاً لا يُنشر مغلقاً:</b> <c>subledgerType</c> و<c>requiredDimensions</c>
    /// لا يحدّهما قيد تحقّق واحد، وهما بيانات المستأجر في دليله. نشرُهما <c>enum</c> كان
    /// سيجعل أول دليل عميل يُدخل نوعاً سادساً <b>يضع الخادم في مخالفة عقده المنشور</b> —
    /// وهو تضييقٌ يفرض v2 لإصلاحه. فيُنشران نصّاً، ويُسمّى المستعمَل اليوم في الوصف.
    /// </para>
    /// </summary>
    private static IReadOnlyList<string> AccountTypes { get; } =
        ["asset", "liability", "equity", "revenue", "expense"];

    /// <summary>الجانب الطبيعي — مغلق بـ<c>ck_account_natural_side</c>.</summary>
    private static IReadOnlyList<string> NaturalSides { get; } = ["debit", "credit"];

    /// <summary>نمط العملة — مغلق بـ<c>ck_account_currency_mode</c>.</summary>
    private static IReadOnlyList<string> CurrencyModes { get; } = ["any", "company_only", "fixed"];

    /// <summary>
    /// اتجاها حركة المخزون — <b>مجموعة مغلقة فعلاً</b>: العمود <c>Direction</c> في
    /// المخطّط لا يقبل غيرهما، والوحدة ترفض ثالثاً باسمه. ولذلك تُنشر <c>enum</c>.
    /// </summary>
    private static IReadOnlyList<string> MovementDirections { get; } = ["IN", "OUT"];

    /// <summary>
    /// أسباب الانحراف في المطابقة — مجموعة مغلقة يُنتجها كود الوحدة وحده، ولا تأتي من
    /// بيانات مستأجر. ولذلك تُنشر <c>enum</c> بخلاف <c>subledgerType</c>.
    /// </summary>
    private static IReadOnlyList<string> DivergenceReasons { get; } =
        ["amount_mismatch", "missing_in_control", "missing_in_subledger"];

    private static IReadOnlyList<string> CostCenterPlans { get; } = Enum.GetNames<CostCenterPlan>();

    /// <summary>أعضاء تعداد حالة مركز التكلفة، مقروءةً من التعداد نفسه.</summary>
    private static IReadOnlyList<string> CostCenterStates { get; } = Enum.GetNames<CostCenterState>();

    private static void WriteCostCenterCodeParameter(Utf8JsonWriter w)
    {
        w.WriteStartObject();
        w.WriteString("name", "costCenterCode");
        w.WriteString("in", "path");
        w.WriteBoolean("required", true);
        w.WriteString("description",
            "رمز مركز التكلفة كما سكّه الخادم. معرّف لا نصّ معروض: لا يُترجَم ولا يتغيّر بإعادة التسمية. / "
            + "The cost centre code as the server minted it. An identifier, not displayed text: never translated, and unchanged by renaming.");
        w.WriteStartObject("schema");
        w.WriteString("type", "string");
        w.WriteString("pattern", "^[a-z0-9._]{1,32}$");
        w.WriteEndObject();
        w.WriteEndObject();
    }

    private static void WriteStringArrayProperty(Utf8JsonWriter w, string name, string ar, string en, int maxLength)
    {
        w.WriteStartObject(name);
        w.WriteString("type", "array");
        w.WriteStartObject("items");
        w.WriteString("type", "string");
        w.WriteNumber("maxLength", maxLength);
        w.WriteEndObject();
        w.WriteString("description", ar + " / " + en);
        w.WriteEndObject();
    }

    private static void WriteEnumArrayProperty(Utf8JsonWriter w, string name, string ar, string en, IReadOnlyList<string> members)
    {
        w.WriteStartObject(name);
        w.WriteString("type", "array");
        w.WriteStartObject("items");
        w.WriteString("type", "string");
        w.WriteStartArray("enum");
        foreach (string member in members)
        {
            w.WriteStringValue(member);
        }

        w.WriteEndArray();
        w.WriteEndObject();
        w.WriteString("description", ar + " / " + en);
        w.WriteEndObject();
    }

    private static void WriteOperation(Utf8JsonWriter w, Operation operation)
    {
        w.WriteStartObject(operation.Method);

        w.WriteString("operationId", operation.OperationId);
        w.WriteString("summary", operation.SummaryAr + " / " + operation.SummaryEn);
        w.WriteString("description", operation.DescriptionAr + "\n\n" + operation.DescriptionEn);

        if (operation.Anonymous)
        {
            w.WriteStartArray("security");
            w.WriteEndArray();
        }

        if (operation.Query.Count > 0)
        {
            w.WriteStartArray("parameters");
            foreach (QueryParameter parameter in operation.Query.OrderBy(static p => p.Name, StringComparer.Ordinal))
            {
                w.WriteStartObject();
                w.WriteString("name", parameter.Name);
                w.WriteString("in", "query");
                w.WriteBoolean("required", parameter.Required);
                w.WriteString("description", parameter.DescriptionAr + " / " + parameter.DescriptionEn);
                w.WriteStartObject("schema");
                switch (parameter.Kind)
                {
                    case "period":
                        w.WriteString("type", "string");
                        w.WriteString("pattern", "^[0-9]{4}-(0[1-9]|1[0-2])$");
                        break;
                    case "year":
                        w.WriteString("type", "string");
                        w.WriteString("pattern", "^[0-9]{4}$");
                        break;
                    case "date":
                        w.WriteString("type", "string");
                        w.WriteString("pattern", "^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$");
                        break;
                    default:
                        w.WriteString("type", "string");
                        w.WriteNumber("maxLength", 32);
                        break;
                }

                w.WriteEndObject();
                w.WriteEndObject();
            }

            w.WriteEndArray();
        }

        if (operation.Body is not null)
        {
            w.WriteStartObject("requestBody");
            w.WriteBoolean("required", true);
            w.WriteStartObject("content");
            w.WriteStartObject("application/json");
            WriteRef(w, "schema", operation.Body);
            w.WriteEndObject();
            w.WriteEndObject();
            w.WriteEndObject();
        }

        w.WriteStartObject("responses");
        WriteResponse(w, operation.Success, "استجابة ناجحة.", "Successful response.", operation.Response,
            operation.ResponseMediaType, operation.ResponseInlineType);

        foreach (Refusal repeat in operation.Repeats ?? [])
        {
            WriteResponse(w, repeat.Status, repeat.Ar, repeat.En, operation.Response);
        }

        if (IdempotentPostings.Contains(operation.OperationId, StringComparer.Ordinal))
        {
            WriteResponse(w, 200,
                "المفتاح نفسه رُحِّل من قبل: الإيصال ذاته و‏alreadyPosted = true. لا قيد ثانٍ.",
                "The same key was already posted: the same receipt with alreadyPosted = true. No second entry.",
                operation.Response);
        }

        if (!operation.Anonymous)
        {
            WriteProblemResponse(w, 401, "اعتماد مفقود أو غير مقبول.", "Missing or unacceptable credential.");
            WriteProblemResponse(w, 403, "الاعتماد لا يبلغ هذه الشركة، أو الاستحقاق يمنع هذا الوصول.", "The credential does not reach this company, or entitlement forbids this access.");
        }

        if (operation.Refusals is { } declared)
        {
            foreach (Refusal refusal in declared)
            {
                WriteProblemResponse(w, refusal.Status, refusal.Ar, refusal.En);
            }
        }
        else if (operation.Body is not null)
        {
            WriteProblemResponse(w, 400, "الجسم لا يطابق العقد: حقل غير معروف، أو مبلغ وصل رمزاً رقمياً، أو صيغة مرفوضة.", "The body does not match the contract: an unknown field, an amount that arrived as a number token, or a refused spelling.");
            WriteProblemResponse(w, 409, "تعارض مع حالة قائمة: فترة مقفلة، أو قيد معكوس من قبل.", "Conflict with existing state: a closed period, or an already-reversed entry.");
            WriteProblemResponse(w, 422, "الطلب مفهوم ومرفوض محاسبياً: قيد غير متوازن، أو دور لا يُحلّ إلى حساب.", "Understood and refused on accounting grounds: an unbalanced entry, or a role that resolves to no account.");
        }

        if (operation.OperationId == "readJournalEntry")
        {
            WriteProblemResponse(w, 501,
                "سطح قراءة القيد المفرد لم يهبط بعد في دفتر الأستاذ. الرمز الثابت: ledger.read.entry_surface_unavailable.",
                "The single-entry read surface has not landed in the ledger yet. Stable code: ledger.read.entry_surface_unavailable.");
        }

        // مشكلات تخصّ هذه العملية وحدها — وما كُتب أعلاه لا يُكتب مرّتين.
        foreach (int status in operation.ProblemStatuses ?? [])
        {
            if (status is (400 or 409 or 422) && operation.Body is not null)
            {
                continue;
            }

            WriteProblemResponse(w, status, ProblemAr(status), ProblemEn(status));
        }

        WriteProblemResponse(w, 500, "عطل في الخادم. لا تفصيل داخلي يعبر — معرّف التتبّع فقط.", "Server failure. No internal detail crosses — only the trace id.");
        w.WriteEndObject();

        w.WriteEndObject();
    }

    /// <summary>
    /// العمليات التي تُعلن 200 إلى جانب 201 لأنّ إعادتها بالهوية نفسها لا تُنشئ شيئاً.
    /// <b>قائمة مكتوبة لا اشتقاق من الاسم:</b> «كل عملية اسمها يبدأ بـpost» كانت ستضمّ
    /// إنشاءَ مسوّدةٍ يُنشئ مستنداً جديداً في كل مرّة، فيُعلن العقد حصانةً لا وجود لها.
    /// </summary>
    private static readonly string[] IdempotentPostings =
    [
        "postCreditNote",
        "postCustomerReceipt",
        "postGoodsReceipt",
        "postJournalEntry",
        "postSalesInvoice",
        "postSupplierBill",
        "postSupplierPayment",
    ];

    private static string ProblemAr(int status) => status switch
    {
        404 => "المورد غير موجود داخل نطاق هذه الشركة.",
        409 => "تعارض مع حالة قائمة: المستند ليس في الحالة التي يقبلها هذا الفعل، أو الفترة مقفلة.",
        422 => "الطلب مفهوم ومرفوض محاسبياً: تجاوز حدّ ائتمان، أو تخصيص يتجاوز المتبقّي، أو دور لا يُحلّ إلى حساب.",
        _ => "رفض.",
    };

    private static string ProblemEn(int status) => status switch
    {
        404 => "The resource does not exist within this company's scope.",
        409 => "Conflict with existing state: the document is not in a state this act accepts, or the period is closed.",
        422 => "Understood and refused on accounting grounds: a credit limit exceeded, an allocation beyond what is outstanding, or a role that resolves to no account.",
        _ => "Refused.",
    };

    private static void WriteResponse(
        Utf8JsonWriter w, int status, string ar, string en, string schema,
        string mediaType = "application/json", string? inlineType = null)
    {
        w.WriteStartObject(status.ToString(System.Globalization.CultureInfo.InvariantCulture));
        w.WriteString("description", ar + " / " + en);
        w.WriteStartObject("content");
        w.WriteStartObject(mediaType);

        if (inlineType is null)
        {
            WriteRef(w, "schema", schema);
        }
        else
        {
            // شكلٌ مضمَّن لا مرجع: البابان الساكنان يخدمان ملفَّين، ولا يوجد نموذج مجال
            // يُسمّى لهما. واختراع مخطّط باسمٍ لأحدهما كان سيضع في العقد اسماً لا يقابله
            // نوع في الشيفرة — وهو أول انفصال بين العقد وما يولّده.
            w.WriteStartObject("schema");
            w.WriteString("type", inlineType);
            w.WriteEndObject();
        }

        w.WriteEndObject();
        w.WriteEndObject();
        w.WriteEndObject();
    }

    private static void WriteProblemResponse(Utf8JsonWriter w, int status, string ar, string en)
    {
        w.WriteStartObject(status.ToString(System.Globalization.CultureInfo.InvariantCulture));
        w.WriteString("description", ar + " / " + en);
        w.WriteStartObject("content");
        w.WriteStartObject("application/problem+json");
        WriteRef(w, "schema", "Problem");
        w.WriteEndObject();
        w.WriteEndObject();
        w.WriteEndObject();
    }

    private static void WriteRef(Utf8JsonWriter w, string property, string schema)
    {
        w.WriteStartObject(property);
        w.WriteString("$ref", "#/components/schemas/" + schema);
        w.WriteEndObject();
    }

    private static void WriteComponents(Utf8JsonWriter w)
    {
        w.WriteStartObject("components");

        w.WriteStartObject("securitySchemes");
        w.WriteStartObject("bearerAuth");
        w.WriteString("type", "http");
        w.WriteString("scheme", "bearer");
        w.WriteString("description",
            "الهوية — المستأجر والمستخدم والشركات المسموح بلوغها — تُشتق من الاعتماد وحده. "
            + "لا ترويسة مستأجر يكتبها العميل، ولا حقل مستأجر في أي جسم. / "
            + "Identity — tenant, user, and reachable companies — is derived from the credential alone. "
            + "No client-written tenant header, and no tenant field in any body.");
        w.WriteEndObject();
        w.WriteEndObject();

        w.WriteStartObject("schemas");
        foreach ((string name, Action<Utf8JsonWriter> write) in Schemas().OrderBy(static s => s.Name, StringComparer.Ordinal))
        {
            w.WriteStartObject(name);
            write(w);
            w.WriteEndObject();
        }

        w.WriteEndObject();

        w.WriteEndObject();
    }

    private static IEnumerable<(string Name, Action<Utf8JsonWriter> Write)> Schemas()
    {
        yield return ("RegisterTenantRequest", static w =>
        {
            w.WriteString("type", "object");
            w.WriteString("description",
                "طلب التسجيل الأول. **ولا حقل خطّة فيه**: هذا بابٌ يُخدَم بلا اعتماد، وحقلٌ يختار منه الطالب "
                + "حزمته يمنح الحزمة الشاملة لمن كتب اسمها. **ولا حقل مستأجر ولا معرّف منشأة**: كلاهما مشتقٌّ "
                + "حتمياً من requestKey، وهو ما يجعل إعادة الإرسال تصل إلى المستأجر نفسه لا إلى ثانٍ. / "
                + "The first-registration request. **It carries no plan field**: this door is served without a credential, "
                + "and a field letting the caller pick their package hands the full one to whoever types its name. **It "
                + "carries no tenant and no company identifier**: both are derived deterministically from requestKey, which "
                + "is what makes a resend reach the same tenant rather than a second one.");
            w.WriteStartObject("properties");
            WriteSignupKeyProperty(w);
            WriteStringProperty(w, "companyNameAr",
                "اسم المنشأة بالعربية — وهو السجلّ لا ترجمته.",
                "The company's Arabic name — the record itself, not a translation of it.", 200);
            WriteArrayRefProperty(w, "nameTranslations", "NameValue",
                "ترجمات اسم المنشأة، مفاتيحها أوسمة BCP-47. ولا حقل إنجليزي ثابت: الإنجليزية واحدة من N. "
                + "وسجل الأسطول يقرأ منها الوسم en لتقاريره، ويرتدّ إلى العربية إن غاب.",
                "The company name's translations, keyed by BCP-47 tags. There is no fixed English field: English is one "
                + "of N. The fleet registry reads the en tag from here for its reporting and falls back to Arabic when absent.");
            WriteStringProperty(w, "ownerNameAr",
                "اسم أول مالك بالعربية — يظهر في قائمة الأعضاء وفي سجلّ التدقيق.",
                "The first owner's Arabic name — it appears in the member list and the audit log.", 200);
            w.WriteEndObject();
            WriteRequired(w, "companyNameAr", "ownerNameAr", "requestKey");
            w.WriteBoolean("additionalProperties", false);
        });

        yield return ("RegisteredTenant", static w =>
        {
            w.WriteString("type", "object");
            w.WriteString("description",
                "مستأجرٌ سُجِّل، ومعه ما يفتح به مالكُه جلسته. وenrolmentCredential يخرج **مرّة واحدة** — المُودَع "
                + "بصمته — وهو معدومٌ عند إعادة الإرسال بالمفتاح نفسه: النتيجة هي هي، والسرّ لا يُسكّ مرّتين. / "
                + "A registered tenant with what opens its owner's session. enrolmentCredential leaves the server **once** — "
                + "only its digest is stored — and it is null on a resend with the same key: the result is the same, and the "
                + "secret is not minted twice.");
            w.WriteStartObject("properties");
            WriteBooleanProperty(w, "alreadyRegistered",
                "‏true حين ردّ هذا الطلبُ تسجيلاً سابقاً بالمفتاح نفسه، ومعه رمز 200 بدل 201.",
                "true when this request returned an earlier registration with the same key, alongside 200 instead of 201.");
            WriteStringProperty(w, "companyId",
                "أول منشأة للمستأجر — وهي التي تُؤسَّس ويُرحَّل فيها.",
                "The tenant's first company — the one that is set up and posted into.", 36);
            WriteNullableStringProperty(w, "enrolmentCredential",
                "اعتماد الانتساب، أو null عند إعادة الإرسال.",
                "The enrolment credential, or null on a resend.", AccessLimits.MaximumPresentedLength);
            WriteNullableStringProperty(w, "enrolmentExpiresAt",
                "لحظة انقضاء الدعوة بصيغة ISO 8601 الدوّارة، أو null عند إعادة الإرسال.",
                "The invitation's expiry in round-trip ISO 8601, or null on a resend.", 64);
            WriteRefProperty(w, "owner", "Membership");
            WriteRefProperty(w, "subscription", "Subscription");
            WriteStringProperty(w, "tenantCode",
                "رمز المستأجر القصير في سجل الأسطول — مشتقٌّ من معرّفه ولا يختاره العميل.",
                "The tenant's short code in the fleet registry — derived from its identifier, never chosen by the client.", 64);
            WriteStringProperty(w, "tenantId", "المستأجر المُنشأ.", "The created tenant.", 36);
            w.WriteEndObject();
            WriteRequired(w, "alreadyRegistered", "companyId", "enrolmentCredential", "enrolmentExpiresAt",
                "owner", "subscription", "tenantCode", "tenantId");
            w.WriteBoolean("additionalProperties", false);
        });

        yield return ("SubscriptionModule", static w =>
        {
            w.WriteString("type", "object");
            w.WriteString("description",
                "وحدةٌ في الاشتراك وحالتها. وpostsJournal يقول إن عملها يبلغ الدفتر، وهو ما يجعل أرضيتها قراءةً "
                + "لا نزعاً عند الانقطاع. / "
                + "A module in the subscription and its state. postsJournal says its work reaches the ledger, which is what "
